'use client';

import React, { useState, useEffect, useCallback, useRef } from 'react';
import {
  ProveedorDB,
  ProveedorCreateInput,
  ProveedorUpdateInput,
  CategoriaProveedorDB,
  getCategoriaStyle,
  CATEGORIA_STYLES,
} from '@/lib/types/proveedor';
import { ProveedorFormModal } from '@/components/modules/proveedores/ProveedorFormModal';
import {
  getProveedores,
  getCategorias,
  createProveedor,
  updateProveedor,
  deactivateProveedor,
} from '@/app/proveedores/actions';

// ÔöÇÔöÇ Mock Data para Cards ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ

const MOCK_TOP_PROVEEDORES = [
  {
    id: '1',
    nombre: 'TechLogistics Global',
    categoria: 'Tecnolog├¡a',
    estado: 'activo',
    calificacion: 98,
    pedidos_activos: 12,
  },
  {
    id: '2',
    nombre: 'Volt & Amp Co.',
    categoria: 'Electricidad',
    estado: 'activo',
    calificacion: 100,
    pedidos_activos: 3,
  },
  {
    id: '3',
    nombre: 'PackSmart SAC',
    categoria: 'Embalaje',
    estado: 'activo',
    calificacion: 91,
    pedidos_activos: 6,
  },
];

// ÔöÇÔöÇ Helpers ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ

function getInitials(name: string): string {
  return name
    .split(' ')
    .slice(0, 2)
    .map((w) => w[0])
    .join('')
    .toUpperCase();
}

// ÔöÇÔöÇ Highlight Cards (Mock Data) ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ

function SupplierHighlightCards() {
  const top3 = MOCK_TOP_PROVEEDORES.sort((a, b) => b.calificacion - a.calificacion).slice(0, 3);

  const cardAccents = [
    { icon: 'precision_manufacturing', color: 'text-primary', bg: 'bg-primary/10', dot: 'border-t-2 border-primary/30' },
    { icon: 'category', color: 'text-secondary', bg: 'bg-secondary/10', dot: 'border-t-2 border-secondary/30' },
    { icon: 'electric_bolt', color: 'text-tertiary', bg: 'bg-tertiary/10', dot: 'border-t-2 border-tertiary/30' },
  ];

  if (top3.length === 0) return null;

  return (
    <div className="grid grid-cols-1 md:grid-cols-3 gap-6 mb-10">
      {top3.map((prov, idx) => {
        const accent = cardAccents[idx];
        return (
          <div
            key={prov.id}
            className={`bg-surface-container rounded-xl p-6 relative overflow-hidden group hover:bg-surface-container-high transition-colors ${accent.dot}`}
          >
            {/* Background icon */}
            <div className="absolute top-0 right-0 p-4 opacity-10 group-hover:opacity-20 transition-opacity pointer-events-none">
              <span
                className={`material-symbols-outlined text-6xl ${accent.color}`}
                style={{ fontVariationSettings: "'FILL' 1" }}
              >
                local_shipping
              </span>
            </div>

            {/* Header */}
            <div className="flex items-center gap-4 mb-6">
              <div className={`w-12 h-12 rounded-lg ${accent.bg} flex items-center justify-center shrink-0`}>
                <span className={`material-symbols-outlined ${accent.color} text-3xl`}>
                  {accent.icon}
                </span>
              </div>
              <div className="min-w-0">
                <h3 className="font-bold text-base text-on-surface truncate">{prov.nombre}</h3>
                <span className={`text-xs font-black uppercase tracking-widest ${accent.color}`}>
                  {prov.categoria}
                </span>
              </div>
            </div>

            {/* Stats mini-grid */}
            <div className="grid grid-cols-2 gap-4">
              <div className="bg-surface-container-low p-3 rounded-lg">
                <p className="text-[10px] uppercase tracking-wider text-on-surface-variant mb-1 font-medium">
                  Calificaci├│n
                </p>
                <p className="text-xl font-black text-tertiary-fixed-dim">{prov.calificacion}%</p>
              </div>
              <div className="bg-surface-container-low p-3 rounded-lg">
                <p className="text-[10px] uppercase tracking-wider text-on-surface-variant mb-1 font-medium">
                  Pedidos Activos
                </p>
                <p className="text-xl font-black text-secondary">
                  {String(prov.pedidos_activos).padStart(2, '0')}
                </p>
              </div>
            </div>
          </div>
        );
      })}
    </div>
  );
}

// ÔöÇÔöÇ Main Page ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ

export default function ProveedoresPage() {
  // ÔöÇÔöÇ Data state
  const [proveedores, setProveedores] = useState<ProveedorDB[]>([]);
  const [categorias, setCategorias] = useState<CategoriaProveedorDB[]>([]);
  const [total, setTotal] = useState(0);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  // ÔöÇÔöÇ Modal state
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [selectedProveedor, setSelectedProveedor] = useState<ProveedorDB | null>(null);

  // ÔöÇÔöÇ Filter state
  const [searchInput, setSearchInput] = useState('');
  const [activeSearch, setActiveSearch] = useState('');
  const [categoriaFilter, setCategoriaFilter] = useState('');
  const [page, setPage] = useState(1);
  const limit = 10;

  const searchTimeout = useRef<ReturnType<typeof setTimeout> | null>(null);

  // ÔöÇÔöÇ Derived pagination ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ
  const totalPages = Math.ceil(total / limit);
  const fromItem = total === 0 ? 0 : (page - 1) * limit + 1;
  const toItem = Math.min(page * limit, total);

  // ÔöÇÔöÇ Fetch helpers ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ

  const fetchPageData = useCallback(async (p: number, search: string, catId: string) => {
    setLoading(true);
    setError(null);
    const result = await getProveedores({ page: p, limit, search, categoria_id: catId });
    if (result.error) {
      setError(result.error);
    } else {
      setProveedores(result.data.data);
      setTotal(result.data.total);
    }
    setLoading(false);
  }, []);

  const fetchCategorias = useCallback(async () => {
    const result = await getCategorias();
    if (!result.error) setCategorias(result.data);
  }, []);

  // ÔöÇÔöÇ Initial load ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ
  useEffect(() => {
    fetchCategorias();
    fetchPageData(1, '', '');
  }, [fetchCategorias, fetchPageData]);

  // ÔöÇÔöÇ Handlers ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ

  const handleSearchChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const value = e.target.value;
    setSearchInput(value);
    if (searchTimeout.current) clearTimeout(searchTimeout.current);
    searchTimeout.current = setTimeout(() => {
      setPage(1);
      setActiveSearch(value);
      fetchPageData(1, value, categoriaFilter);
    }, 350);
  };

  const handleCategoriaChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
    const val = e.target.value;
    setCategoriaFilter(val);
    setPage(1);
    fetchPageData(1, activeSearch, val);
  };

  const handlePageChange = (newPage: number) => {
    setPage(newPage);
    fetchPageData(newPage, activeSearch, categoriaFilter);
  };

  const handleOpenNew = () => {
    setSelectedProveedor(null);
    setIsModalOpen(true);
  };

  const handleOpenEdit = (p: ProveedorDB) => {
    setSelectedProveedor(p);
    setIsModalOpen(true);
  };

  const handleDeactivate = async (id: string) => {
    const result = await deactivateProveedor(id);
    if (!result.error) {
      await fetchPageData(page, activeSearch, categoriaFilter);
    }
  };

  const handleSave = async (
    data: ProveedorCreateInput | ProveedorUpdateInput,
    mode: 'create' | 'edit',
  ): Promise<{ success: boolean; error?: string }> => {
    if (mode === 'edit' && selectedProveedor) {
      const result = await updateProveedor(selectedProveedor.id, data as ProveedorUpdateInput);
      if (result.error) return { success: false, error: result.error };
    } else {
      const result = await createProveedor(data as ProveedorCreateInput);
      if (result.error) return { success: false, error: result.error };
    }
    // Refresh list
    await fetchPageData(mode === 'create' ? 1 : page, activeSearch, categoriaFilter);
    if (mode === 'create') setPage(1);
    return { success: true };
  };

  // ÔöÇÔöÇ Render ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ
  return (
    <div className="p-8 space-y-0">
      {/* ÔöÇÔöÇ Page Header ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ */}
      <div className="flex flex-col md:flex-row md:items-end justify-between gap-4 mb-8">
        <div>
          <h2 className="text-3xl font-extrabold text-on-surface tracking-tight mb-1">
            Directorio de Proveedores
          </h2>
          <p className="text-on-surface-variant font-medium">
            Gestiona y optimiza tu cadena de suministro.
          </p>
        </div>
        <button
          id="btn-nuevo-proveedor"
          onClick={handleOpenNew}
          className="flex items-center gap-2 px-6 py-3 bg-gradient-to-br from-primary-dim to-primary text-on-primary-container font-bold rounded-xl shadow-lg shadow-primary/20 hover:scale-[1.02] active:scale-95 transition-all"
        >
          <span
            className="material-symbols-outlined"
            style={{ fontVariationSettings: "'FILL' 1" }}
          >
            add
          </span>
          A├▒adir Proveedor
        </button>
      </div>

      {/* ÔöÇÔöÇ Highlight Cards ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ */}
      <SupplierHighlightCards />

      {/* ÔöÇÔöÇ Error banner ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ */}
      {error && (
        <div className="mb-4 flex items-center gap-2 px-4 py-3 bg-error/10 border border-error/30 rounded-lg text-sm text-error">
          <span className="material-symbols-outlined text-base">error</span>
          {error}
        </div>
      )}

      {/* ÔöÇÔöÇ Filters & Table Section ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ */}
      <div className="bg-surface-container-low rounded-xl overflow-hidden border border-outline-variant/10 shadow-2xl shadow-black/40">
        {/* Table Controls */}
        <div className="p-6 flex flex-col md:flex-row gap-4 items-center justify-between mb-4">
          <div className="flex items-center gap-4 w-full md:w-auto">
            <div className="relative w-full md:w-72">
              <span className="material-symbols-outlined absolute left-3 top-1/2 -translate-y-1/2 text-on-surface-variant">search</span>
              <input
                className="w-full bg-surface-container border border-outline-variant/20 rounded-lg pl-10 pr-4 py-2 text-sm focus:ring-2 focus:ring-primary/40 focus:border-primary text-on-surface transition-all outline-none"
                placeholder="Buscar por nombre, contacto o email..."
                type="text"
                value={searchInput}
                onChange={handleSearchChange}
              />
            </div>
            <select
              className="bg-surface-container border border-outline-variant/20 rounded-lg px-4 py-2 text-sm text-on-surface focus:ring-2 focus:ring-primary/40 transition-all outline-none appearance-none cursor-pointer"
              onChange={handleCategoriaChange}
              value={categoriaFilter}
            >
              <option value="">Categor├¡a: Todas</option>
              {categorias.map((cat) => (
                <option key={cat.id} value={cat.id}>{cat.nombre}</option>
              ))}
            </select>
          </div>

          <div className="flex items-center gap-2">
            <span className="text-xs text-on-surface-variant font-medium">
              {total === 0 ? 'Sin resultados' : `Mostrando ${fromItem}-${toItem} de ${total}`}
            </span>
            <div className="flex gap-1">
              <button
                disabled={page <= 1 || loading}
                onClick={() => handlePageChange(Math.max(1, page - 1))}
                className="p-1.5 bg-surface-container-highest rounded-md text-on-surface-variant hover:text-on-surface transition-colors disabled:opacity-40 disabled:cursor-not-allowed"
              >
                <span className="material-symbols-outlined text-lg">chevron_left</span>
              </button>
              <button
                disabled={page >= totalPages || totalPages === 0 || loading}
                onClick={() => handlePageChange(Math.min(totalPages, page + 1))}
                className="p-1.5 bg-surface-container-highest rounded-md text-on-surface-variant hover:text-on-surface transition-colors disabled:opacity-40 disabled:cursor-not-allowed"
              >
                <span className="material-symbols-outlined text-lg">chevron_right</span>
              </button>
            </div>
          </div>
        </div>

